questions.answer:
// price.js
export function formatPrice(cents, currency = "INR") {
  if (!Number.isInteger(cents) || cents < 0) {
    throw new RangeError("cents must be a non-negative integer");
  }
  return new Intl.NumberFormat("en-IN", {
    style: "currency",
    currency,
  }).format(cents / 100);
}

// price.test.js
import { describe, it, expect } from "vitest";
import { formatPrice } from "./price.js";

describe("formatPrice", () => {
  it("formats rupees", () => {
    expect(formatPrice(129900)).toBe("₹1,299.00");
  });

  it("formats zero", () => {
    expect(formatPrice(0)).toBe("₹0.00");
  });

  it("rejects negative or fractional cents", () => {
    expect(() => formatPrice(-1)).toThrow(RangeError);
    expect(() => formatPrice(10.5)).toThrow("non-negative integer");
  });
});

The key points are the guard before formatting, dividing by 100 because Intl works in major units, and testing the throw with expect(fn).toThrow rather than calling the function directly (which would fail the test before the assertion). Intl output can vary slightly by ICU version, so assert the exact string only when the runtime is pinned; otherwise assert with toContain("1,299").

