// counter.test.js
import { beforeEach, it, expect } from "vitest";
import { mountCounter } from "./counter.js";

beforeEach(() => {
  document.body.innerHTML = "";
  mountCounter(document.body);
});

questions.answer:
// counter.js
export function mountCounter(root) {
  root.innerHTML = `
    <p id="count">0</p>
    <button id="inc">+1</button>
    <button id="reset">Reset</button>
  `;
  let count = 0;
  const out = root.querySelector("#count");

  root.querySelector("#inc").addEventListener("click", () => {
    count += 1;
    out.textContent = String(count);
  });

  root.querySelector("#reset").addEventListener("click", () => {
    count = 0;
    out.textContent = "0";
  });
}

// counter.test.js
it("increments and resets", () => {
  const inc = document.querySelector("#inc");
  inc.click();
  inc.click();
  expect(document.querySelector("#count").textContent).toBe("2");

  document.querySelector("#reset").click();
  expect(document.querySelector("#count").textContent).toBe("0");
});

The test clicks the real buttons and reads the rendered text, so it survives a refactor from let to a data object. Reset the DOM in beforeEach so tests do not leak nodes into each other. Avoid asserting internal variables; assert what the user sees.

questions.question:
This test passes even when the code is wrong. Why?

it("loads Kakade", () => {
  fetchUser(1).then((user) => {
    expect(user.name).toBe("Asha");
  });
});

questions.answer:
The test function returns undefined, so Vitest/Jest considers the test finished as soon as the synchronous part returns. The .then callback runs later, after the test has already been marked passed; if its assertion throws, the rejection is unhandled and the suite may still be green. This is the classic false positive in async testing.

The fix is to return the promise or make the test async and await it:

it("loads Kakade", async () => {
  const user = await fetchUser(1);
  expect(user.name).toBe("Kakade");
});

A second safe form is to return the chain: return fetchUser(1).then((user) => expect(user.name).toBe("Kakade")). Both tell the runner to wait. For rejections use await expect(fetchUser(999)).rejects.toThrow("Not found") so the rejection is observed, not left unhandled.

questions.question:
What happens here, and which matcher should be used?

const user = { name: "Kakade", skills: ["js"] };
expect(user).toBe({ name: "Kakade", skills: ["js"] });
expect([1, 2]).toBe([1, 2]);

questions.answer:
Both assertions fail. toBe uses Object.is, which compares references for objects and arrays. The literal on the right is a different object in memory even though its contents look identical, so the check is false. The same applies to two arrays with the same numbers.

Use toEqual for a recursive value comparison:

expect(user).toEqual({ name: "Kakade", skills: ["js"] });
expect([1, 2]).toEqual([1, 2]);

toStrictEqual is the stricter sibling: it also checks prototypes and undefined properties, so toEqual({ a: undefined }) matches {}, while toStrictEqual({ a: undefined }) does not match {}. Use toBe only for primitives and for checking identity (expect(result).toBe(user) when the function should return the same reference).
